111	      if (!org || !shouldRunForOrg(org, now)) continue;
112	
113	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
114	
115	      const windowEnd = toIsoTimestamp(now);
116	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
117	
118	      for (const recipientId of await listDigestRecipients(orgId)) {
119	        try {
120	          const bundle = await buildDigest(
121	            orgId,
122	            recipientId,
123	            windowStart,
124	            windowEnd,
