278	/**
279	 * Minimal in-process job queue: enqueue, drain, retry with backoff. Jobs never run inside a request.
280	 */
281	import { createLogger } from "@/lib/logger";
282	import { toIsoTimestamp } from "@/types/common";
283	import type { IsoTimestamp } from "@/types/common";
284	
285	export type QueuedJob = {
286	  id: string;
287	  kind: JobKind;
288	  runAt: IsoTimestamp;
289	  attempts: number;
290	  payload: Readonly<Record<string, unknown>>;
291	};
292	
293	export type JobKind =
294	  | "digest-email"
295	  | "overdue-issues"
296	  | "webhook-delivery"
297	  | "usage-rollup"
298	  | "search-reindex"
299	  | "cleanup-archived"
300	  | "trial-expiry";
301	
302	/** Attempts after which a job is dropped rather than retried again. */
303	const MAX_ATTEMPTS = 5;
304	
305	/** How many jobs `drain()` takes in one pass when no limit is given. */
306	const DEFAULT_DRAIN = 25;
307	
308	const logger = createLogger("job-queue");
309	
310	/**
311	 * The queue lives in module scope: Taskflow runs one server process and the
312	 * scheduler is started from `instrumentation.ts`, so there is no second
313	 * consumer to coordinate with. Swapping this for a real broker means
314	 * reimplementing these four functions and nothing else.
315	 */
316	const pending: QueuedJob[] = [];
317	
318	/** Idempotent on `id`: re-enqueuing a job keeps the earlier `runAt`. */
319	export function enqueue(job: QueuedJob): void {
320	  if (pending.some((queued) => queued.id === job.id)) return;
321	  pending.push(job);
322	}
323	
324	/**
325	 * Runs everything that is due, oldest first. A handler that throws is put back
326	 * with an exponential delay until `MAX_ATTEMPTS`, then dropped with a log line
327	 * — an infinitely retrying job is worse than a lost one.
328	 */
329	export async function drain(limit: number = DEFAULT_DRAIN): Promise<number> {
330	  const now = new Date().toISOString();
331	  const due = pending
332	    .filter((job) => job.runAt <= now)
333	    .sort((a, b) => (a.runAt < b.runAt ? -1 : 1))
334	    .slice(0, Math.max(0, limit));
335	
336	  let completed = 0;
337	
338	  for (const job of due) {
339	    remove(job.id);
340	
341	    try {
342	      await runHandler(job);
343	      completed += 1;
344	    } catch (error) {
345	      const attempts = job.attempts + 1;
346	
347	      if (attempts >= MAX_ATTEMPTS) {
348	        logger.error("job dropped after max attempts", {
349	          id: job.id,
350	          kind: job.kind,
351	          attempts,
352	        });
353	        continue;
354	      }
355	
356	      pending.push({
357	        ...job,
358	        attempts,
359	        runAt: toIsoTimestamp(new Date(Date.now() + backoffMs(attempts))),
360	      });
361	
362	      logger.warn("job retry scheduled", {
363	        id: job.id,
364	        kind: job.kind,
365	        attempts,
366	        reason: error instanceof Error ? error.message : String(error),
367	      });
368	    }
369	  }
370	
371	  return completed;
372	}
373	
