443	 * Interval-based scheduler started from `src/instrumentation.ts`; decides which job kind is due.
444	 */
445	import { createLogger } from "@/lib/logger";
446	import { drain, enqueue, pendingCount } from "./queue";
447	import { toIsoTimestamp } from "@/types/common";
448	import type { JobKind } from "./queue";
449	
450	/** How often `tick()` runs once the scheduler is started. */
451	const TICK_INTERVAL_MS = 60_000;
452	
453	/** Minimum gap between two runs of the same job kind, in minutes. */
454	const CADENCE_MINUTES: Readonly<Record<JobKind, number>> = {
455	  "digest-email": 60,
456	  "overdue-issues": 60,
457	  "webhook-delivery": 1,
458	  "usage-rollup": 15,
459	  "search-reindex": 1_440,
460	  "cleanup-archived": 1_440,
461	  "trial-expiry": 360,
462	};
463	
464	const logger = createLogger("job-scheduler");
465	
466	let timer: ReturnType<typeof setInterval> | null = null;
467	const lastRunAt = new Map<JobKind, number>();
468	
469	/**
470	 * Starts the interval. Idempotent, and `unref()`ed so a pending tick never
471	 * keeps a process alive — a scheduler that blocks shutdown is worse than one
472	 * that misses the last tick.
473	 */
474	export function startScheduler(): void {
475	  if (timer !== null) return;
476	
477	  timer = setInterval(() => {
478	    void tick(new Date()).catch((error: unknown) => {
479	      logger.error("scheduler tick failed", {
480	        reason: error instanceof Error ? error.message : String(error),
481	      });
482	    });
483	  }, TICK_INTERVAL_MS);
484	
485	  timer.unref?.();
486	  logger.info("scheduler started", { intervalMs: TICK_INTERVAL_MS });
487	}
488	
489	export function stopScheduler(): void {
490	  if (timer === null) return;
491	  clearInterval(timer);
492	  timer = null;
493	  lastRunAt.clear();
494	}
495	
496	export function isSchedulerRunning(): boolean {
497	  return timer !== null;
498	}
499	
500	/**
501	 * One pass: enqueue whatever cadence says is due, then drain the queue. Split
502	 * out from the interval so tests can drive it with an explicit clock instead
503	 * of waiting a minute.
504	 */
505	export async function tick(now: Date): Promise<void> {
506	  for (const kind of Object.keys(CADENCE_MINUTES) as JobKind[]) {
507	    if (!isDue(kind, now)) continue;
508	
509	    lastRunAt.set(kind, now.getTime());
510	    enqueue({
511	      id: `${kind}:${Math.floor(now.getTime() / 60_000)}`,
512	      kind,
513	      runAt: toIsoTimestamp(now),
514	      attempts: 0,
515	      payload: {},
516	    });
517	  }
518	
519	  const completed = await drain();
520	  if (completed > 0 || pendingCount() > 0) {
521	    logger.debug("tick complete", { completed, pending: pendingCount() });
522	  }
523	}
524	
525	function isDue(kind: JobKind, now: Date): boolean {
526	  const previous = lastRunAt.get(kind);
527	  if (previous === undefined) return true;
528	  return now.getTime() - previous >= CADENCE_MINUTES[kind] * 60_000;
529	}
