import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); resetOverdueTracking(); });
afterAll(() => cleanup());
it("scales", async () => {
  const tenants = [];
  for (let i = 0; i < 60; i++) {
    const t = await createTenant(`t${i}`);
    const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
    await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { dueAt: "2026-01-01T00:00:00.000Z" }), t.userIds.owner, n);
    tenants.push(t);
  }
  await orgRepo.archiveOrg(tenants[0].org.id);
  const seen = new Set<string>();
  const off = subscribe("issue.overdue", (p) => { seen.add(p.orgId); });
  await runOverdueIssueJob(new Date("2026-06-01T00:00:00Z"));
  off();
  expect(seen.size).toBe(59);
  expect(seen.has(tenants[0].org.id)).toBe(false);
  const all = new Set<string>();
  for (let r = 0; r < 3; r++) {
    const before = await usageRepo.listOrgIdsForRollup(25);
    await runUsageRollupJob(new Date());
    await usageRepo.incrementUsage(tenants[5].org.id, { issuesUsed: 1 });
    before.forEach((id) => all.add(id));
  }
  expect(all.size).toBe(59);
});
